#include <bits/stdc++.h>

using namespace std;

const int mod = 1000000007;
int N, M, p[1000009], p2[1000009];

int mul(int x, int y) {
    return static_cast<int>(1LL * x * y % mod);
}

void adto(int &x, int y) {
    x += y;
    if (x >= mod) x -= mod;
}

int power(int x, int y) {
    int result = 1;
    while (y > 0) {
        if (y & 1) result = mul(result, x);
        x = mul(x, x);
        y >>= 1;
    }
    return result;
}

int main() {
    scanf("%d %d", &N, &M);
    p[0] = p2[0] = 1;

    for (int i = 1; i <= N; i++) {
        p[i] = mul(p[i - 1], M);
        p2[i] = mul(p2[i - 1], 2 * M - 1);
    }

    int ans = power(M, N);
    for (int P = 1; P <= N; P++)
        adto(ans, mul(p[N - P + 1], p2[P - 1]));

    printf("%d\n", ans);
    return 0;
}

